/**
 * Pure-JS HMAC (RFC 2104), shaped like Python's `hmac` module.
 *
 * The digest module is passed in the same way Python does it (`hmac.new(key, msg, hashlib.sha1)`),
 * so this file never hard-depends on a particular hash beyond the default import below.
 */

import * as sha1 from './sha1.mjs';

const IPAD = 0x36;
const OPAD = 0x5c;

/** Fallback block size when the digest module does not advertise one (SHA-1/MD5/SHA-256 all use 64). */
const DEFAULT_BLOCK_SIZE = 64;

/**
 * Coerce an input to a Uint8Array view without copying when possible.
 * @param {Uint8Array|ArrayBuffer|ArrayBufferView|number[]} data
 * @returns {Uint8Array}
 */
function toBytes(data) {
  if (data instanceof Uint8Array) return data;
  if (ArrayBuffer.isView(data)) return new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
  if (data instanceof ArrayBuffer) return new Uint8Array(data);
  if (Array.isArray(data)) return Uint8Array.from(data);
  throw new TypeError('expected bytes (Uint8Array), got ' + typeof data);
}

/**
 * Resolve the "constructor" of a hashlib-like module object. We accept `new` (Python's spelling,
 * exported here only on the default object because it is a reserved word), `create`, a bare
 * callable module, or the module's default export.
 * @param {object|Function} digestmod
 * @returns {(data?: Uint8Array) => {update: Function, digest: Function, copy: Function}}
 */
function resolveFactory(digestmod) {
  if (typeof digestmod === 'function') return digestmod;
  for (const mod of [digestmod, digestmod && digestmod.default]) {
    if (!mod) continue;
    if (typeof mod.new === 'function') return mod.new.bind(mod);
    if (typeof mod.create === 'function') return mod.create.bind(mod);
  }
  throw new TypeError('digestmod must expose new()/create()');
}

/**
 * Read the block size advertised by a hashlib-like module object.
 * @param {object|Function} digestmod
 * @returns {number}
 */
function resolveBlockSize(digestmod) {
  for (const mod of [digestmod, digestmod && digestmod.default]) {
    if (mod && Number.isInteger(mod.block_size) && mod.block_size > 0) return mod.block_size;
  }
  return DEFAULT_BLOCK_SIZE;
}

/**
 * HMAC keyed-hash object. Mirrors Python's `hmac.HMAC`: `update()` feeds the inner hash,
 * `digest()` is non-destructive, and `copy()` clones the (already keyed) state cheaply.
 */
export class HMAC {
  /**
   * @param {Uint8Array} key raw key bytes
   * @param {Uint8Array|null} [msg] optional initial message bytes
   * @param {object} [digestmod] hashlib-like module (defaults to the bundled SHA-1)
   */
  constructor(key, msg = null, digestmod = sha1) {
    // `copy()` builds instances through the private clone path, skipping all key derivation.
    if (key === CLONE_TOKEN) return;

    const factory = resolveFactory(digestmod);
    const blockSize = resolveBlockSize(digestmod);
    let keyBytes = toBytes(key);

    // RFC 2104: keys longer than one block are replaced by their digest; shorter keys are
    // zero-padded. A key of exactly blockSize bytes is used verbatim (no hashing).
    if (keyBytes.length > blockSize) keyBytes = toBytes(factory(keyBytes).digest());

    const inner = new Uint8Array(blockSize);
    const outer = new Uint8Array(blockSize);
    for (let i = 0; i < blockSize; i++) {
      const b = i < keyBytes.length ? keyBytes[i] : 0;
      inner[i] = b ^ IPAD;
      outer[i] = b ^ OPAD;
    }

    this._factory = factory;
    this._inner = factory(inner);
    this._outer = factory(outer);
    this.block_size = blockSize;

    const probe = this._inner.copy().digest();
    this.digest_size = probe.length;

    if (msg !== null && msg !== undefined) this.update(msg);
  }

  /**
   * Feed message bytes to the inner hash.
   * @param {Uint8Array} msg
   * @returns {HMAC} this, for chaining
   */
  update(msg) {
    this._inner.update(toBytes(msg));
    return this;
  }

  /**
   * @returns {Uint8Array} the MAC of the bytes fed so far; the object stays usable afterwards.
   */
  digest() {
    const outer = this._outer.copy();
    outer.update(toBytes(this._inner.copy().digest()));
    return toBytes(outer.digest());
  }

  /**
   * Cheap clone of the already-keyed state. PBKDF2 relies on this to avoid re-deriving the
   * ipad/opad blocks on every one of its iterations.
   * @returns {HMAC}
   */
  copy() {
    const clone = new HMAC(CLONE_TOKEN);
    clone._factory = this._factory;
    clone._inner = this._inner.copy();
    clone._outer = this._outer.copy();
    clone.block_size = this.block_size;
    clone.digest_size = this.digest_size;
    return clone;
  }
}

/** Sentinel that tells the constructor to skip key setup (used only by `copy()`). */
const CLONE_TOKEN = Symbol('hmac.clone');

/**
 * Convenience factory mirroring Python's `hmac.new(key, msg, digestmod)`.
 * @param {Uint8Array} key
 * @param {Uint8Array|null} [msg]
 * @param {object} [digestmod]
 * @returns {HMAC}
 */
export function create(key, msg = null, digestmod = sha1) {
  return new HMAC(key, msg, digestmod);
}

export default { HMAC, new: create, create };

