// Throwaway reference SHA-1 for testing hmac.mjs in isolation (matches the sha1.mjs contract).
export const digest_size = 20;
export const block_size = 64;

function rotl(x, n) {
  return ((x << n) | (x >>> (32 - n))) >>> 0;
}

export class SHA1 {
  constructor() {
    this.h = new Uint32Array([0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476, 0xc3d2e1f0]);
    this.buf = new Uint8Array(64);
    this.bufLen = 0;
    this.total = 0;
  }

  _block(bytes, off) {
    const w = new Uint32Array(80);
    for (let i = 0; i < 16; i++) {
      w[i] = ((bytes[off + i * 4] << 24) | (bytes[off + i * 4 + 1] << 16) |
              (bytes[off + i * 4 + 2] << 8) | bytes[off + i * 4 + 3]) >>> 0;
    }
    for (let i = 16; i < 80; i++) w[i] = rotl(w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16], 1);
    let [a, b, c, d, e] = this.h;
    for (let i = 0; i < 80; i++) {
      let f, k;
      if (i < 20) { f = (b & c) | (~b & d); k = 0x5a827999; }
      else if (i < 40) { f = b ^ c ^ d; k = 0x6ed9eba1; }
      else if (i < 60) { f = (b & c) | (b & d) | (c & d); k = 0x8f1bbcdc; }
      else { f = b ^ c ^ d; k = 0xca62c1d6; }
      const t = (rotl(a, 5) + (f >>> 0) + e + k + w[i]) >>> 0;
      e = d; d = c; c = rotl(b, 30); b = a; a = t;
    }
    this.h[0] = (this.h[0] + a) >>> 0;
    this.h[1] = (this.h[1] + b) >>> 0;
    this.h[2] = (this.h[2] + c) >>> 0;
    this.h[3] = (this.h[3] + d) >>> 0;
    this.h[4] = (this.h[4] + e) >>> 0;
  }

  update(data) {
    let i = 0;
    this.total += data.length;
    if (this.bufLen > 0) {
      const need = 64 - this.bufLen;
      const take = Math.min(need, data.length);
      this.buf.set(data.subarray(0, take), this.bufLen);
      this.bufLen += take;
      i = take;
      if (this.bufLen === 64) { this._block(this.buf, 0); this.bufLen = 0; }
    }
    for (; i + 64 <= data.length; i += 64) this._block(data, i);
    if (i < data.length) {
      this.buf.set(data.subarray(i), this.bufLen);
      this.bufLen += data.length - i;
    }
    return this;
  }

  digest() {
    const c = this.copy();
    const bitLenHi = Math.floor(c.total / 0x20000000) >>> 0;
    const bitLenLo = (c.total * 8) >>> 0;
    const pad = [0x80];
    while ((c.total + pad.length) % 64 !== 56) pad.push(0);
    c.update(Uint8Array.from(pad));
    const tail = new Uint8Array(8);
    new DataView(tail.buffer).setUint32(0, bitLenHi);
    new DataView(tail.buffer).setUint32(4, bitLenLo);
    c.update(tail);
    const out = new Uint8Array(20);
    for (let i = 0; i < 5; i++) new DataView(out.buffer).setUint32(i * 4, c.h[i]);
    return out;
  }

  copy() {
    const n = new SHA1();
    n.h = this.h.slice();
    n.buf = this.buf.slice();
    n.bufLen = this.bufLen;
    n.total = this.total;
    return n;
  }
}

export function create(initial) {
  const h = new SHA1();
  if (initial) h.update(initial);
  return h;
}

export default { digest_size, block_size, new: create, create };

import { HMAC, create } from './hmac.mjs';
import * as sha1 from './sha1.mjs';

const hex = (u8) => Array.from(u8, (b) => b.toString(16).padStart(2, '0')).join('');
const bytes = (s) => new TextEncoder().encode(s);
const rep = (b, n) => new Uint8Array(n).fill(b);
const fromHex = (s) => Uint8Array.from(s.match(/../g).map((x) => parseInt(x, 16)));

let fails = 0;
function check(name, got, want) {
  if (got !== want) { fails++; console.log(`FAIL ${name}\n  got  ${got}\n  want ${want}`); }
  else console.log(`ok   ${name}  ${got}`);
}

// --- Independent naive HMAC (written differently: one-shot concat, no streaming) ---
function sha1once(u8) { return sha1.create(u8).digest(); }
function naiveHmac(key, msg) {
  let k = key;
  if (k.length > 64) k = sha1once(k);
  const kp = new Uint8Array(64); kp.set(k);
  const ip = new Uint8Array(64 + msg.length);
  const op = new Uint8Array(64 + 20);
  for (let i = 0; i < 64; i++) { ip[i] = kp[i] ^ 0x36; op[i] = kp[i] ^ 0x5c; }
  ip.set(msg, 64);
  op.set(sha1once(ip), 64);
  return sha1once(op);
}

// --- RFC 2202 HMAC-SHA1 vectors ---
const vectors = [
  ['rfc2202 #1', rep(0x0b, 20), bytes('Hi There'), 'b617318655057264e28bc0b6fb378c8ef146be00'],
  ['rfc2202 #2', bytes('Jefe'), bytes('what do ya want for nothing?'), 'effcdf6ae5eb2fa2d27416d5f184df9c259a7c79'],
  ['rfc2202 #3', rep(0xaa, 20), rep(0xdd, 50), '125d7342b9ac11cd91a39af48aa17b4f63f175d3'],
  ['rfc2202 #4', fromHex('0102030405060708090a0b0c0d0e0f10111213141516171819'), rep(0xcd, 50), '4c9007f4026250c6bc8414f9bf50c86c2d7235da'],
  ['rfc2202 #5', rep(0x0c, 20), bytes('Test With Truncation'), '4c1a03424b55e07fe7f27be1d58bb9324a9a5a04'],
  ['rfc2202 #6', rep(0xaa, 80), bytes('Test Using Larger Than Block-Size Key - Hash Key First'), 'aa4ae5e15272d00e95705637ce8a3b55ed402112'],
  ['rfc2202 #7', rep(0xaa, 80), bytes('Test Using Larger Than Block-Size Key and Larger Than One Block-Size Data'), 'e8e99d0f45237d786d6bbaa7965c7808bbff1a91'],
];
for (const [name, key, msg, want] of vectors) {
  check(name, hex(create(key, msg, sha1).digest()), want);
}

// --- Key-length boundary sweep, cross-checked against the naive implementation ---
for (const klen of [0, 1, 20, 63, 64, 65, 80, 128, 200]) {
  const key = new Uint8Array(klen).map((_, i) => (i * 37 + 11) & 0xff);
  for (const mlen of [0, 1, 55, 56, 64, 119, 200]) {
    const msg = new Uint8Array(mlen).map((_, i) => (i * 91 + 3) & 0xff);
    check(`sweep k=${klen} m=${mlen}`, hex(create(key, msg, sha1).digest()), hex(naiveHmac(key, msg)));
  }
}

// exactly-64-byte key must NOT be pre-hashed (verify by contradiction)
const k64 = rep(0xaa, 64);
const notPrehashed = hex(create(k64, bytes('x'), sha1).digest());
const prehashed = hex(create(sha1.create(k64).digest(), bytes('x'), sha1).digest());
check('64-byte key not pre-hashed', notPrehashed !== prehashed ? 'distinct' : 'same', 'distinct');
check('64-byte key matches naive', notPrehashed, hex(naiveHmac(k64, bytes('x'))));
// 65-byte key IS pre-hashed
const k65 = rep(0xaa, 65);
check('65-byte key pre-hashed', hex(create(k65, bytes('x'), sha1).digest()),
  hex(create(sha1.create(k65).digest(), bytes('x'), sha1).digest()));

// --- streaming update() equals one-shot ---
const sKey = bytes('streaming-key');
const parts = [bytes('abc'), rep(0x11, 100), bytes(''), rep(0x22, 33)];
const whole = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
{ let o = 0; for (const p of parts) { whole.set(p, o); o += p.length; } }
const stream = create(sKey, null, sha1);
for (const p of parts) stream.update(p);
check('streaming == one-shot', hex(stream.digest()), hex(create(sKey, whole, sha1).digest()));

// --- digest() is non-destructive and repeatable ---
const nd = create(sKey, bytes('hello'), sha1);
const d1 = hex(nd.digest());
const d2 = hex(nd.digest());
check('digest repeatable', d1, d2);
nd.update(bytes('!'));
check('digest after further update', hex(nd.digest()), hex(create(sKey, bytes('hello!'), sha1).digest()));

// --- copy() independence + the PBKDF2 fast path ---
const base = create(rep(0x5a, 20), null, sha1);
const c1 = base.copy();
const c2 = base.copy();
c1.update(bytes('one'));
c2.update(bytes('two'));
check('copy c1', hex(c1.digest()), hex(create(rep(0x5a, 20), bytes('one'), sha1).digest()));
check('copy c2', hex(c2.digest()), hex(create(rep(0x5a, 20), bytes('two'), sha1).digest()));
check('base untouched by copies', hex(base.digest()), hex(create(rep(0x5a, 20), new Uint8Array(0), sha1).digest()));
const c3 = c1.copy();
c3.update(bytes('-more'));
check('copy of a copy', hex(c3.digest()), hex(create(rep(0x5a, 20), bytes('one-more'), sha1).digest()));
check('copy instanceof HMAC', String(c1 instanceof HMAC), 'true');
check('copy digest_size', String(c1.digest_size), '20');
check('copy block_size', String(c1.block_size), '64');

// --- digestmod forms: namespace object, default object, bare factory fn ---
check('digestmod default-obj', hex(create(bytes('k'), bytes('m'), sha1.default).digest()), hex(naiveHmac(bytes('k'), bytes('m'))));
check('digestmod bare fn', hex(create(bytes('k'), bytes('m'), sha1.create).digest()), hex(naiveHmac(bytes('k'), bytes('m'))));
check('digestmod default arg', hex(create(bytes('k'), bytes('m')).digest()), hex(naiveHmac(bytes('k'), bytes('m'))));

// --- PBKDF2-HMAC-SHA1 end-to-end via copy() fast path (RFC 6070) ---
function pbkdf2(pw, salt, iters, dkLen) {
  const proto = create(pw, null, sha1);
  const out = new Uint8Array(dkLen);
  let off = 0, i = 1;
  while (off < dkLen) {
    const h = proto.copy();
    h.update(salt);
    h.update(Uint8Array.from([(i >>> 24) & 0xff, (i >>> 16) & 0xff, (i >>> 8) & 0xff, i & 0xff]));
    let u = h.digest();
    const f = u.slice();
    for (let j = 1; j < iters; j++) {
      const hh = proto.copy();
      hh.update(u);
      u = hh.digest();
      for (let k = 0; k < f.length; k++) f[k] ^= u[k];
    }
    const take = Math.min(20, dkLen - off);
    out.set(f.subarray(0, take), off);
    off += take; i++;
  }
  return out;
}
check('pbkdf2 c=1', hex(pbkdf2(bytes('password'), bytes('salt'), 1, 20)), '0c60c80f961f0e71f3a9b524af6012062fe037a6');
check('pbkdf2 c=2', hex(pbkdf2(bytes('password'), bytes('salt'), 2, 20)), 'ea6c014dc72d6f8ccd1ed92ace1d41f0d8de8957');
check('pbkdf2 c=4096', hex(pbkdf2(bytes('password'), bytes('salt'), 4096, 20)), '4b007901b765489abead49d926f721d065a429c1');
check('pbkdf2 25-byte dk', hex(pbkdf2(bytes('passwordPASSWORDpassword'), bytes('saltSALTsaltSALTsaltSALTsaltSALTsalt'), 4096, 25)),
  '3d2eec4fe41c849b80c8d83662c0e44a8b291a964cf2f07038');

// --- given project test cases ---
const given = [
  ["p'_xyB9J", '$2b$12$aTIircdJsS8iO3WFg3aKsE', 500, '8dc01b919e750ff1d42d9066b1cb46cbd79fbaca'],
  ['=BH[kuEw', 'salt_740344', 10000, 'b0384e5dbe9a85ba12a97d330410bb28cb062190'],
  ['RxgG9oiZ', 'FeKORdjj', 5000, '6352bbf03b1567f6d68e560c03dece654146ca25'],
  [',XD0fO8{', '$2b$12$v3g32CgH6DaUjA3PjeEYqv', 1000, '9f322ad1a21e4b891f19bd297e641e7119dd665a'],
  ['密码パス', 'ソルト盐', 100, '4429b29d3ddbffbe3bbcdf31fc40fff0874ab542'],
  ['café', 'naïve', 100, 'f014dbf5a80c0193c046b7b11e1b14ba2d9b280a'],
  ['😀🔑', '🧂', 50, 'a5dac9673a93a95cc562585930bdd0d92a3dd093'],
  ['', '', 1, '1e437a1c79d75be61e91141dae20affc4892cc99'],
  ['A'.repeat(63), 's', 10, null],
  ['A'.repeat(64), 's', 10, null],
  ['A'.repeat(65), 's', 10, null],
];
for (const [pw, salt, it, want] of given) {
  const got = hex(pbkdf2(bytes(pw), bytes(salt), it, 20));
  if (want) check(`given ${JSON.stringify(pw)}`, got, want);
  else console.log(`info key-len ${pw.length}: ${got}`);
}

// --- perf sanity: 10000 iterations must be fast ---
const t0 = Date.now();
pbkdf2(bytes('=BH[kuEw'), bytes('salt_740344'), 10000, 20);
console.log(`perf 10000 iters: ${Date.now() - t0} ms`);

console.log(fails === 0 ? '\nALL PASS' : `\n${fails} FAILURES`);
process.exit(fails === 0 ? 0 : 1);

